  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../app/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================\n// User Models (Existing - giữ nguyên)\n// ============================================\n\nmodel User {\n  id    Int     @id @default(autoincrement())\n  email String  @unique\n  name  String?\n  posts Post[]\n}\n\nmodel Post {\n  id        Int     @id @default(autoincrement())\n  title     String\n  content   String?\n  published Boolean @default(false)\n  authorId  Int\n  author    User    @relation(fields: [authorId], references: [id])\n}\n\n// ============================================\n// E-Commerce Models (Enhanced)\n// ============================================\n\n// User for E-Commerce (authentication)\nmodel UserP {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  name      String?\n  phone     String?\n  address   String?\n  city      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  orders  Order[]\n  carts   Cart[]\n  reviews Review[]\n\n  @@map(\"users_ecommerce\")\n}\n\n// Product Model (Enhanced)\nmodel Product {\n  id          String   @id @default(uuid())\n  name        String\n  description String\n  price       Float\n  imageUrl    String?\n  stock       Int      @default(0)\n  category    String? // Áo thun, Áo khoác, Quần, Phụ kiện...\n  featured    Boolean  @default(false) // Sản phẩm nổi bật\n  onSale      Boolean  @default(false) // Đang giảm giá\n  salePrice   Float? // Giá sale (nếu có)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  cartItems  CartItem[]\n  orderItems OrderItem[]\n  reviews    Review[]\n\n  @@map(\"products\")\n}\n\n// Cart Model (Giỏ hàng)\nmodel Cart {\n  id        String   @id @default(uuid())\n  userId    String\n  user      UserP    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  items CartItem[]\n\n  @@unique([userId]) // Mỗi user chỉ có 1 giỏ hàng\n  @@map(\"carts\")\n}\n\n// Cart Item (Sản phẩm trong giỏ hàng)\nmodel CartItem {\n  id        String   @id @default(uuid())\n  cartId    String\n  cart      Cart     @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  quantity  Int      @default(1)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([cartId, productId]) // Mỗi sản phẩm chỉ xuất hiện 1 lần trong giỏ hàng\n  @@map(\"cart_items\")\n}\n\n// Order Model (Đơn hàng)\nmodel Order {\n  id     String @id @default(uuid())\n  userId String\n  user   UserP  @relation(fields: [userId], references: [id])\n\n  // Order Information\n  orderNumber String      @unique @default(uuid())\n  status      OrderStatus @default(PENDING)\n\n  // Shipping Information\n  shippingName    String\n  shippingEmail   String\n  shippingPhone   String\n  shippingAddress String\n  shippingCity    String\n  shippingNote    String?\n\n  // Payment Information\n  paymentMethod PaymentMethod @default(COD)\n  paymentStatus PaymentStatus @default(UNPAID)\n\n  // Price Information\n  subtotal    Float // Tổng tiền hàng\n  shippingFee Float @default(0) // Phí vận chuyển\n  discount    Float @default(0) // Giảm giá\n  total       Float // Tổng thanh toán\n\n  // Timestamps\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  completedAt DateTime? // Thời gian hoàn thành đơn\n\n  // Relations\n  items OrderItem[]\n\n  @@map(\"orders\")\n}\n\n// Order Item (Sản phẩm trong đơn hàng)\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n\n  // Product snapshot at time of order\n  productName  String\n  productPrice Float\n  productImage String?\n\n  quantity Int\n  subtotal Float // quantity * productPrice\n\n  createdAt DateTime @default(now())\n\n  @@map(\"order_items\")\n}\n\n// Review Model (Đánh giá sản phẩm)\nmodel Review {\n  id        String  @id @default(uuid())\n  userId    String\n  user      UserP   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  rating  Int // 1-5 sao\n  comment String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, productId]) // Mỗi user chỉ review 1 lần mỗi sản phẩm\n  @@map(\"reviews\")\n}\n\n// ============================================\n// Enums\n// ============================================\n\nenum OrderStatus {\n  PENDING // Chờ xác nhận\n  CONFIRMED // Đã xác nhận\n  PROCESSING // Đang xử lý\n  SHIPPING // Đang giao hàng\n  DELIVERED // Đã giao hàng\n  CANCELLED // Đã hủy\n  REFUNDED // Đã hoàn tiền\n}\n\nenum PaymentMethod {\n  COD // Thanh toán khi nhận hàng\n  BANK // Chuyển khoản ngân hàng\n  MOMO // Ví MoMo\n  VNPAY // VNPay\n  ZALOPAY // ZaloPay\n}\n\nenum PaymentStatus {\n  UNPAID // Chưa thanh toán\n  PAID // Đã thanh toán\n  REFUNDED // Đã hoàn tiền\n  FAILED // Thanh toán thất bại\n}\n",
